-- Transactional API. All clocks and hashes below are generated by PostgreSQL.
-- Replay is safe; the original baseline migration is intentionally unchanged.
alter table prepmeds_audit.agent_runs drop constraint if exists agent_runs_state_check;
alter table prepmeds_audit.agent_runs add constraint agent_runs_state_check check(state in ('CLAIMED','PASS','FAIL','EXPIRED','SUPERSEDED'));

create or replace function prepmeds_audit.evidence_deficiencies(p_group text,p jsonb,p_commit text) returns jsonb
language plpgsql stable set search_path='' as $$
declare errors jsonb := '[]'; s jsonb; q jsonb; t jsonb; c jsonb; k text; expected jsonb; g prepmeds_audit.review_groups; required text[]; ids text[];
begin
  select * into g from prepmeds_audit.review_groups where group_id=p_group;
  if jsonb_typeof(p) is distinct from 'object' then return '["EVIDENCE_OBJECT_REQUIRED"]'; end if;
  if p->>'schema_version' is distinct from '1' or p->>'group_id' is distinct from p_group then errors:=errors||'"SCHEMA_OR_GROUP_MISMATCH"'; end if;
  if p_commit is null or p_commit !~ '^[0-9a-f]{40}$' then errors:=errors||'"EXACT_GITHUB_COMMIT_REQUIRED"'; end if;
  select coalesce(jsonb_agg(medication_id order by medication_id),'[]') into expected from prepmeds_audit.review_unit_members where group_id=p_group;
  if jsonb_typeof(p->'medication_ids') is distinct from 'array' then errors:=errors||'"MAPPING_REQUIRED"';
  elsif expected='[]' or (select jsonb_agg(v order by v) from jsonb_array_elements_text(p->'medication_ids') v) is distinct from expected then errors:=errors||'"EXACT_CANONICAL_MAPPING_REQUIRED"'; end if;
  if g.formulation_key='UNADJUDICATED' or g.is_container or p#>>'{formulation,key}' is distinct from g.formulation_key or p#>>'{formulation,adjudicated}' is distinct from 'true' then errors:=errors||'"FORMULATION_NOT_ADJUDICATED"'; end if;
  foreach k in array array['route','regimen','scope'] loop
    if coalesce(length(p#>>array['formulation',k]),0)=0 then errors:=errors||to_jsonb('FORMULATION_'||upper(k)||'_REQUIRED'); end if;
  end loop;
  if p->>'clinical_reviewed' is distinct from 'false' or p->>'patient_facing_enabled' is distinct from 'false' then errors:=errors||'"ACTIVATION_BOUNDARY_REQUIRED"'; end if;
  if p->>'evidence_kind' not in ('GUIDELINE','SYNTHETIC_TEST') or p->>'evidence_kind' is null then errors:=errors||'"EVIDENCE_KIND_REQUIRED"'; end if;
  if p->>'evidence_kind'='SYNTHETIC_TEST' and (select environment from prepmeds_audit.runtime_config) <> 'test' then errors:=errors||'"SYNTHETIC_EVIDENCE_NOT_OPERATIONAL"'; end if;
  if jsonb_typeof(p->'sources') is distinct from 'array' then return errors||'"SOURCES_REQUIRED"'; end if;
  if jsonb_array_length(p->'sources')=0 then errors:=errors||'"SOURCES_REQUIRED"'; end if;
  for s in select value from jsonb_array_elements(p->'sources') loop
    if coalesce(s->>'id','')='' or s->>'id'=any(coalesce(ids,'{}')) then errors:=errors||'"SOURCE_ID_INVALID_OR_DUPLICATE"'; end if;
    ids:=array_append(ids,s->>'id');
    if s->>'access' is distinct from 'RETRIEVED' or coalesce(s->>'document_sha256','') !~ '^[0-9a-f]{64}$' or coalesce(s->>'primary_url','') !~ '^https://[^ /]+' then errors:=errors||'"PRIMARY_SOURCE_UNVERIFIED"'; end if;
    foreach k in array array['title','society','version','publication_date'] loop
      if coalesce(length(s->>k),0)=0 then errors:=errors||to_jsonb('SOURCE_'||upper(k)||'_REQUIRED'); end if;
    end loop;
    if jsonb_typeof(s->'passages') is distinct from 'array' then errors:=errors||'"LOCATED_PASSAGES_REQUIRED"';
    elsif jsonb_array_length(s->'passages')=0 then errors:=errors||'"LOCATED_PASSAGES_REQUIRED"';
    else
      for q in select value from jsonb_array_elements(s->'passages') loop
        if coalesce(q->>'locator','')='' or coalesce(q->>'quote','')='' or q->>'sha256' is distinct from encode(sha256(convert_to(q->>'quote','UTF8')),'hex') then errors:=errors||'"PASSAGE_HASH_OR_LOCATION_INVALID"'; end if;
      end loop;
    end if;
  end loop;
  if jsonb_typeof(p->'comparisons') is distinct from 'array' then errors:=errors||'"COMPARISONS_REQUIRED"';
  else
    -- Antithrombotics have mandatory comparison coverage; nonapplicability must be explicit.
    required:=case when p->>'domain'='antithrombotic' then array['ASGE-2016','BSG-ESGE-2021','ACG-CAG-2022','CHEST-2022','AHA-ACC-2024'] else array[]::text[] end;
    foreach k in array required loop
      if (select count(*) from jsonb_array_elements(p->'comparisons') x where x->>'guideline'=k)<>1 then errors:=errors||to_jsonb('COMPARISON_REQUIRED:'||k); end if;
    end loop;
    for c in select value from jsonb_array_elements(p->'comparisons') loop
      if coalesce(c->>'guideline','')='' or c->>'status' is null or c->>'status' not in ('COMPARED','NOT_SPECIFIED','NOT_APPLICABLE') then errors:=errors||'"COMPARISON_STATUS_REQUIRED"'; end if;
      if c->>'status'='NOT_APPLICABLE' then
        if coalesce(length(c->>'rationale'),0)<8 then errors:=errors||'"NONAPPLICABILITY_RATIONALE_REQUIRED"'; end if;
      elsif not coalesce((c->>'source_id')=any(ids),false) then errors:=errors||'"COMPARISON_SOURCE_MISSING"'; end if;
    end loop;
  end if;
  if jsonb_typeof(p->'recommendations') is distinct from 'array' then errors:=errors||'"RECOMMENDATIONS_REQUIRED"';
  elsif jsonb_array_length(p->'recommendations')=0 then errors:=errors||'"RECOMMENDATIONS_REQUIRED"';
  else
    for q in select value from jsonb_array_elements(p->'recommendations') loop
      if not coalesce((q->>'source_id')=any(ids),false) or coalesce(q->>'passage_sha256','')='' or not exists(select 1 from jsonb_array_elements(p->'sources') x cross join lateral jsonb_array_elements(x->'passages') y where x->>'id'=q->>'source_id' and y->>'sha256'=q->>'passage_sha256') then errors:=errors||'"RECOMMENDATION_PASSAGE_MISSING"'; end if;
      foreach k in array array['renal','hepatic','indication','bleeding_risk','thrombotic_risk','bridging','strength','certainty','exceptions'] loop
        if not(q?k) or q->k='null'::jsonb or q->k='""'::jsonb then errors:=errors||to_jsonb('RECOMMENDATION_FIELD_REQUIRED:'||k); end if;
      end loop;
      foreach k in array array['interruption','resumption'] loop
        t:=q->k;
        if t->>'status' is distinct from 'NOT_SPECIFIED' then
          if t->>'status' is distinct from 'SPECIFIED' or jsonb_typeof(t->'min') is distinct from 'number' or jsonb_typeof(t->'max') is distinct from 'number' or coalesce(t->>'unit','') not in ('hours','calendar_days','full_days','doses') or coalesce(t->>'anchor','')='' or coalesce(t->>'comparison','') not in ('EXACT','AT_LEAST','GREATER_THAN','RANGE') then errors:=errors||to_jsonb('EXACT_TIMING_REQUIRED:'||k);
          elsif (t->>'min')::numeric<0 or (t->>'max')::numeric<(t->>'min')::numeric then errors:=errors||'"INVALID_INTERVAL"'; end if;
        elsif coalesce(t->>'reason','')='' then errors:=errors||'"NOT_SPECIFIED_REASON_REQUIRED"'; end if;
      end loop;
    end loop;
  end if;
  if jsonb_typeof(p->'conflicts') is distinct from 'array' or jsonb_typeof(p->'exceptions') is distinct from 'array' then errors:=errors||'"CONFLICTS_AND_EXCEPTIONS_REQUIRED"'; end if;
  if jsonb_typeof(p->'tests') is distinct from 'array' then errors:=errors||'"EXECUTED_TESTS_REQUIRED"';
  elsif jsonb_array_length(p->'tests')=0 then errors:=errors||'"EXECUTED_TESTS_REQUIRED"';
  else
    for t in select value from jsonb_array_elements(p->'tests') loop
      if t->>'status' is distinct from 'PASS' or t->>'commit_sha' is distinct from p_commit or coalesce(t->>'run_url','') !~ '^https://github.com/jedmedasr/PREP-MEDS/actions/runs/[0-9]+$' or coalesce(t->>'command','')='' then errors:=errors||'"EXACT_HEAD_TEST_RECEIPT_REQUIRED"'; end if;
    end loop;
  end if;
  return errors;
exception when invalid_parameter_value or invalid_text_representation then return errors||'"MALFORMED_EVIDENCE_FIELDS"';
end $$;

-- Import is administrative, not agent evidence acceptance. It never grants A/B PASS.
create or replace function prepmeds_audit.import_catalog(p_key text,p_commit text,p jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare old prepmeds_audit.import_receipts; g jsonb; m jsonb; existing prepmeds_audit.review_groups; mapped prepmeds_audit.canonical_mapping; h text; n integer:=0;
begin
  if coalesce(p_key,'')='' or coalesce(p_commit,'') !~ '^[0-9a-f]{40}$' or jsonb_typeof(p->'groups') is distinct from 'array' or jsonb_typeof(p->'medications') is distinct from 'array' then raise exception 'INVALID_IMPORT'; end if;
  perform pg_advisory_xact_lock(hashtextextended('prepmeds:catalog-import',0));
  h:=prepmeds_audit.hash_json(p);
  select * into old from prepmeds_audit.import_receipts where import_key=p_key;
  if found then
    if old.content_hash<>h or old.source_commit<>p_commit then raise exception 'IMPORT_KEY_REUSE'; end if;
    return jsonb_build_object('replayed',true,'hash',h);
  end if;
  if (select count(distinct x->>'group_id') from jsonb_array_elements(p->'groups') x)<>jsonb_array_length(p->'groups') or (select count(distinct x->>'medication_id') from jsonb_array_elements(p->'medications') x)<>jsonb_array_length(p->'medications') then raise exception 'DUPLICATE_IMPORT_IDENTITIES'; end if;
  for g in select value from jsonb_array_elements(p->'groups') loop
    if coalesce(g->>'group_id','') !~ '^ING-' or jsonb_typeof(g->'ingredient_ids') is distinct from 'array' then raise exception 'INVALID_GROUP_IMPORT'; end if;
    select * into existing from prepmeds_audit.review_groups where group_id=g->>'group_id' for update;
    if found and (existing.bucket<>(g->>'bucket')::integer or existing.owner_lane<>g->>'owner_lane') then raise exception 'ALLOCATION_CONFLICT'; end if;
    insert into prepmeds_audit.review_groups(group_id,bucket,owner_lane,ingredient_ids,import_snapshot)
    values(g->>'group_id',(g->>'bucket')::integer,g->>'owner_lane',g->'ingredient_ids',g)
    on conflict(group_id) do nothing;
    -- Preserve existing operational status and history; new imports are separate receipts/events.
    insert into prepmeds_audit.custody_events(group_id,event_type,details) values(g->>'group_id','IMPORTED_AGENT_A_WIP',jsonb_build_object('commit',p_commit,'import_key',p_key,'snapshot',g,'verified',false));
  end loop;
  for m in select value from jsonb_array_elements(p->'medications') loop
    if coalesce(m->>'medication_id','') !~ '^MED-' or coalesce(m->>'canonical_name','')='' then raise exception 'INVALID_CANONICAL_IMPORT'; end if;
    select * into mapped from prepmeds_audit.canonical_mapping where medication_id=m->>'medication_id' for update;
    if found and (mapped.group_id<>m->>'group_id' or mapped.canonical_name<>m->>'canonical_name') then raise exception 'CANONICAL_IMPORT_CONFLICT'; end if;
    insert into prepmeds_audit.canonical_mapping(medication_id,group_id,canonical_name,import_snapshot,source_commit)
    values(m->>'medication_id',m->>'group_id',m->>'canonical_name',m,p_commit) on conflict(medication_id) do nothing;
    insert into prepmeds_audit.review_unit_members(group_id,medication_id) values(m->>'group_id',m->>'medication_id') on conflict do nothing;
    n:=n+1;
  end loop;
  insert into prepmeds_audit.import_receipts(import_key,content_hash,source_commit,payload) values(p_key,h,p_commit,p);
  return jsonb_build_object('replayed',false,'groups',jsonb_array_length(p->'groups'),'canonical_ids',n,'hash',h,'agent_a_completed',0,'agent_b_verified',0,'evidence_complete',0);
end $$;

create or replace function prepmeds_audit.recover_expired(p_lane text) returns integer
language plpgsql set search_path='' as $$
declare g prepmeds_audit.review_groups; r prepmeds_audit.agent_runs; n integer:=0;
begin
  for g in select * from prepmeds_audit.review_groups where owner_lane=p_lane and state in ('AGENT_A_CLAIMED','AGENT_B_CLAIMED') order by group_id for update skip locked loop
    select * into r from prepmeds_audit.agent_runs where run_id=case when g.state='AGENT_A_CLAIMED' then g.latest_a_run else g.latest_b_run end for update;
    if r.state='CLAIMED' and r.lease_until<=clock_timestamp() then
      update prepmeds_audit.agent_runs set state='EXPIRED',finished_at=clock_timestamp() where run_id=r.run_id;
      update prepmeds_audit.review_groups set state=case when r.agent='B' then 'AWAITING_B' when r.previous_state='DISPUTED' then 'DISPUTED' else 'QUEUED' end,updated_at=clock_timestamp() where group_id=g.group_id;
      insert into prepmeds_audit.custody_events(group_id,run_id,event_type,details) values(g.group_id,r.run_id,'LEASE_EXPIRED',jsonb_build_object('revision',r.revision,'agent',r.agent,'progress_preserved',true));
      n:=n+1;
    end if;
  end loop;
  return n;
end $$;

create or replace function prepmeds_audit.dispatch(p_token text,p_action text,p_payload jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare a prepmeds_audit.agent_principals; cfg prepmeds_audit.runtime_config; g prepmeds_audit.review_groups; r prepmeds_audit.agent_runs; prior prepmeds_audit.agent_runs; e prepmeds_audit.evidence_revisions; req prepmeds_audit.dispatch_requests;
  key text; h text; errors jsonb; reply jsonb; stage text; n integer; ttl integer; evidence jsonb; verification jsonb; s jsonb; q jsonb; v jsonb; u jsonb; unit_id text; medication text; covered text[]:='{}'; expected text[]; revision integer; outcome text;
begin
  if p_token is null or length(p_token)<32 then raise exception 'UNAUTHORIZED' using errcode='42501'; end if;
  select * into a from prepmeds_audit.agent_principals where credential_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') and enabled;
  if not found then raise exception 'UNAUTHORIZED' using errcode='42501'; end if;
  if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>2000000 then raise exception 'INVALID_OR_OVERSIZED_PAYLOAD'; end if;
  select * into cfg from prepmeds_audit.runtime_config where singleton;
  if p_action='status' then
    return jsonb_build_object('enabled',cfg.enabled,'environment',cfg.environment,'project_ref',cfg.project_ref,'observed_at_utc',clock_timestamp(),'lane',a.owner_lane,
      'canonical_ids',(select count(*) from prepmeds_audit.canonical_mapping),
      'provisional_groups',(select count(*) from prepmeds_audit.review_groups where parent_group_id is null),
      'states',(select coalesce(jsonb_object_agg(state,n),'{}') from (select state,count(*) n from prepmeds_audit.review_groups where owner_lane=a.owner_lane and not is_container group by state) x),
      'agent_a_completed',(select count(*) from prepmeds_audit.agent_runs x join prepmeds_audit.review_groups y using(group_id) where y.owner_lane=a.owner_lane and x.agent='A' and x.state='PASS' and x.principal_id is not null),
      'agent_b_verified',(select count(*) from prepmeds_audit.agent_runs x join prepmeds_audit.review_groups y using(group_id) where y.owner_lane=a.owner_lane and x.agent='B' and x.state='PASS' and x.principal_id is not null),
      'patient_facing_authorized',false);
  end if;
  if not cfg.enabled then raise exception 'LEDGER_NOT_ACTIVATED'; end if;
  if p_action in ('next','claim') then
    n:=prepmeds_audit.recover_expired(a.owner_lane);
    stage:=case when exists(select 1 from prepmeds_audit.review_groups where owner_lane=a.owner_lane and state='AWAITING_B' and not is_container) then 'B' else 'A' end;
    if p_action='next' then return jsonb_build_object('next_agent',stage,'recovered',n,'observed_at_utc',clock_timestamp(),'lane',a.owner_lane); end if;
    key:=p_payload->>'idempotency_key';
    if coalesce(key,'') !~ '^[A-Za-z0-9:_./-]{8,180}$' then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;
    perform 1 from prepmeds_audit.agent_principals where principal_id=a.principal_id for update;
    select * into req from prepmeds_audit.dispatch_requests where principal_id=a.principal_id and request_key=key;
    if found then
      if req.request_hash<>prepmeds_audit.hash_json(p_payload) then raise exception 'IDEMPOTENCY_KEY_REUSE'; end if;
      select * into r from prepmeds_audit.agent_runs where run_id=req.run_id;
      return req.response || jsonb_build_object('replayed',true,'run',case when r.run_id is null then null else to_jsonb(r) end,'execution_authorized',coalesce(r.state='CLAIMED' and r.lease_until>clock_timestamp(),false));
    end if;
    if exists(select 1 from prepmeds_audit.agent_runs where principal_id=a.principal_id and state='CLAIMED') then raise exception 'PRINCIPAL_ALREADY_HAS_ACTIVE_EXECUTION'; end if;
    if a.agent='A' and stage='B' then
      reply:=jsonb_build_object('run',null,'next_agent','B','reason','AWAITING_INDEPENDENT_B','execution_authorized',false);
    else
      select * into g from prepmeds_audit.review_groups x where x.owner_lane=a.owner_lane and not x.is_container
        and ((a.agent='A' and x.state in ('QUEUED','DISPUTED')) or (a.agent='B' and x.state='AWAITING_B' and exists(select 1 from prepmeds_audit.agent_runs ar join prepmeds_audit.agent_principals ap on ap.principal_id=ar.principal_id where ar.run_id=x.latest_a_run and ap.identity_id<>a.identity_id)))
        order by case when x.state='DISPUTED' then 0 else 1 end,x.bucket,x.group_id for update skip locked limit 1;
      if not found then reply:=jsonb_build_object('run',null,'next_agent',stage,'reason','NO_ELIGIBLE_WORK','execution_authorized',false);
      else
        ttl:=coalesce((p_payload->>'lease_seconds')::integer,2700);
        if ttl<1 or ttl>3600 or (cfg.environment<>'test' and ttl<60) then raise exception 'INVALID_LEASE'; end if;
        revision:=g.current_revision+case when a.agent='A' then 1 else 0 end;
        insert into prepmeds_audit.agent_runs(group_id,agent,revision,attempt,principal_id,context_id,previous_state,claimed_at,lease_until)
        values(g.group_id,a.agent,revision,(select coalesce(max(attempt),0)+1 from prepmeds_audit.agent_runs where group_id=g.group_id and agent=a.agent and agent_runs.revision=revision),a.principal_id,gen_random_uuid()::text,g.state,clock_timestamp(),clock_timestamp()+make_interval(secs=>ttl)) returning * into r;
        update prepmeds_audit.review_groups set state=case when a.agent='A' then 'AGENT_A_CLAIMED' else 'AGENT_B_CLAIMED' end,latest_a_run=case when a.agent='A' then r.run_id else latest_a_run end,latest_b_run=case when a.agent='B' then r.run_id else latest_b_run end,updated_at=clock_timestamp() where group_id=g.group_id;
        insert into prepmeds_audit.custody_events(group_id,run_id,event_type,details) values(g.group_id,r.run_id,'CLAIMED',jsonb_build_object('principal',a.principal_id,'identity',a.identity_id,'agent',a.agent,'revision',r.revision,'context',r.context_id,'lease_until',r.lease_until));
        reply:=jsonb_build_object('run',to_jsonb(r),'execution_authorized',true,'next_agent',a.agent);
      end if;
    end if;
    insert into prepmeds_audit.dispatch_requests(principal_id,request_key,request_hash,run_id,response) values(a.principal_id,key,prepmeds_audit.hash_json(p_payload),r.run_id,reply);
    return reply;
  end if;
  select * into r from prepmeds_audit.agent_runs where run_id=(p_payload->>'run_id')::uuid and principal_id=a.principal_id;
  if not found then raise exception 'EXECUTION_NOT_OWNED' using errcode='42501'; end if;
  select * into g from prepmeds_audit.review_groups where group_id=r.group_id for update;
  select * into r from prepmeds_audit.agent_runs where run_id=r.run_id for update;
  if p_action='get' then
    return jsonb_build_object('run',to_jsonb(r),'group',to_jsonb(g),'current_evidence',(select to_jsonb(x) from prepmeds_audit.evidence_revisions x where group_id=g.group_id and x.revision=g.current_revision),'imports',(select coalesce(jsonb_agg(jsonb_build_object('commit',i.source_commit,'group',j)),'[]') from prepmeds_audit.import_receipts i cross join lateral jsonb_array_elements(i.payload->'groups') j where j->>'group_id'=coalesce(g.parent_group_id,g.group_id)));
  end if;
  h:=prepmeds_audit.hash_json(jsonb_build_object('action',p_action,'payload',p_payload));
  if r.state<>'CLAIMED' then
    if p_action in ('submit','verify','split') and r.result_hash=h then return jsonb_build_object('replayed',true,'run_id',r.run_id,'run_state',r.state,'current_state',g.state,'execution_authorized',false); end if;
    raise exception 'EXECUTION_ALREADY_FINISHED';
  end if;
  if r.lease_until<=clock_timestamp() then raise exception 'LEASE_EXPIRED'; end if;
  if (r.agent='A' and (g.latest_a_run<>r.run_id or g.state<>'AGENT_A_CLAIMED' or r.revision<>g.current_revision+1)) or (r.agent='B' and (g.latest_b_run<>r.run_id or g.state<>'AGENT_B_CLAIMED' or r.revision<>g.current_revision)) then raise exception 'STALE_EXECUTION'; end if;
  if p_action='renew' then
    ttl:=coalesce((p_payload->>'lease_seconds')::integer,2700);
    if ttl<1 or ttl>3600 or (cfg.environment<>'test' and ttl<60) then raise exception 'INVALID_LEASE'; end if;
    update prepmeds_audit.agent_runs set lease_until=greatest(lease_until,clock_timestamp()+make_interval(secs=>ttl)) where run_id=r.run_id returning * into r;
    insert into prepmeds_audit.custody_events(group_id,run_id,event_type,details) values(g.group_id,r.run_id,'LEASE_RENEWED',jsonb_build_object('lease_until',r.lease_until));
    return jsonb_build_object('run',to_jsonb(r));
  elsif p_action='checkpoint' then
    if r.result_hash is distinct from h then
      update prepmeds_audit.agent_runs set scenario_evidence=p_payload->'progress',result_hash=h where run_id=r.run_id;
      insert into prepmeds_audit.custody_events(group_id,run_id,event_type,details) values(g.group_id,r.run_id,'PROGRESS_SAVED',jsonb_build_object('progress',p_payload->'progress','hash',h));
    end if;
    return jsonb_build_object('saved',true,'run_id',r.run_id);
  elsif p_action='split' then
    if a.agent<>'A' or g.parent_group_id is not null or g.current_revision<>0 or jsonb_typeof(p_payload->'units') is distinct from 'array' or jsonb_array_length(p_payload->'units')=0 then raise exception 'FORMULATION_SPLIT_NOT_ALLOWED'; end if;
    select array_agg(medication_id order by medication_id) into expected from prepmeds_audit.canonical_mapping where group_id=g.group_id;
    for u in select value from jsonb_array_elements(p_payload->'units') loop
      if coalesce(u->>'key','') !~ '^[a-z0-9][a-z0-9-]{2,100}$' or coalesce(u#>>'{scope,route}','')='' or coalesce(u#>>'{scope,regimen}','')='' or jsonb_typeof(u->'medication_ids') is distinct from 'array' or jsonb_array_length(u->'medication_ids')=0 then raise exception 'INVALID_FORMULATION_SCOPE'; end if;
      unit_id:=g.group_id||'::'||(u->>'key');
      insert into prepmeds_audit.review_groups(group_id,parent_group_id,bucket,owner_lane,ingredient_ids,formulation_key) values(unit_id,g.group_id,g.bucket,g.owner_lane,g.ingredient_ids,u->>'key');
      for medication in select jsonb_array_elements_text(u->'medication_ids') loop
        if not coalesce(medication=any(expected),false) or (medication=any(covered) and u#>>'{scope,requires_confirmation}' is distinct from 'true') then raise exception 'FORMULATION_MAPPING_OUTSIDE_PARENT_OR_AMBIGUOUS'; end if;
        covered:=array_append(covered,medication);
        insert into prepmeds_audit.review_unit_members values(unit_id,medication,u->'scope');
      end loop;
      insert into prepmeds_audit.custody_events(group_id,event_type,details) values(unit_id,'FORMULATION_UNIT_PROPOSED',jsonb_build_object('parent',g.group_id,'proposing_run',r.run_id,'scope',u));
    end loop;
    if (select array_agg(distinct x order by x) from unnest(covered) x) is distinct from expected then raise exception 'FORMULATION_SPLIT_LOST_CANONICAL_IDS'; end if;
    update prepmeds_audit.agent_runs set state='SUPERSEDED',finished_at=clock_timestamp(),result_hash=h where run_id=r.run_id;
    update prepmeds_audit.review_groups set is_container=true,state='QUEUED',updated_at=clock_timestamp() where group_id=g.group_id;
    insert into prepmeds_audit.custody_events(group_id,run_id,event_type,details) values(g.group_id,r.run_id,'SPLIT_INTO_REVIEW_UNITS',p_payload->'units');
    return jsonb_build_object('split',true,'parent',g.group_id,'clinical_reviewed',false);
  elsif p_action='submit' then
    if a.agent<>'A' then raise exception 'AGENT_A_REQUIRED'; end if;
    evidence:=p_payload->'evidence';
    if jsonb_typeof(evidence) is distinct from 'object' then raise exception 'EVIDENCE_OBJECT_REQUIRED'; end if;
    errors:=prepmeds_audit.evidence_deficiencies(g.group_id,evidence,p_payload->>'github_commit');
    insert into prepmeds_audit.evidence_revisions(group_id,revision,a_run_id,content_hash,github_commit,payload,mapping_snapshot,deficiencies)
    values(g.group_id,r.revision,r.run_id,prepmeds_audit.hash_json(evidence),p_payload->>'github_commit',evidence,(select jsonb_agg(to_jsonb(m) order by medication_id) from prepmeds_audit.review_unit_members m where group_id=g.group_id),errors) returning * into e;
    outcome:=case when errors='[]' then 'PASS' else 'FAIL' end;
    update prepmeds_audit.agent_runs set state=outcome,evidence_hash=e.content_hash,evidence_commit=e.github_commit,source_citations=coalesce(evidence->'sources','[]'),test_evidence=coalesce(evidence->'tests','[]'),discrepancies=errors,result_hash=h,finished_at=clock_timestamp() where run_id=r.run_id;
    update prepmeds_audit.review_groups set current_revision=r.revision,state=case when outcome='PASS' then 'AWAITING_B' when r.previous_state='DISPUTED' then 'DISPUTED' else 'QUEUED' end,updated_at=clock_timestamp() where group_id=g.group_id returning * into g;
    insert into prepmeds_audit.custody_events(group_id,run_id,event_type,details) values(g.group_id,r.run_id,case when outcome='PASS' then 'AGENT_A_SUBMITTED' else 'AGENT_A_INCOMPLETE' end,jsonb_build_object('revision',r.revision,'hash',e.content_hash,'deficiencies',errors));
    return jsonb_build_object('run_id',r.run_id,'revision',r.revision,'evidence_hash',e.content_hash,'state',g.state,'deficiencies',errors,'clinical_reviewed',false,'patient_facing_authorized',false);
  elsif p_action='verify' then
    if a.agent<>'B' then raise exception 'AGENT_B_REQUIRED'; end if;
    select * into e from prepmeds_audit.evidence_revisions where group_id=g.group_id and evidence_revisions.revision=g.current_revision;
    select * into prior from prepmeds_audit.agent_runs where run_id=e.a_run_id;
    if e.content_hash is distinct from p_payload->>'evidence_hash' or e.revision::text is distinct from p_payload->>'revision' then raise exception 'STALE_EVIDENCE_REVISION'; end if;
    if a.identity_id=(select identity_id from prepmeds_audit.agent_principals where principal_id=prior.principal_id) or r.context_id=prior.context_id then raise exception 'SELF_VERIFICATION_FORBIDDEN'; end if;
    verification:=p_payload->'verification';
    outcome:=p_payload->>'outcome';
    if outcome is null or outcome not in ('PASS','FAIL') or jsonb_typeof(verification) is distinct from 'object' then raise exception 'INVALID_VERDICT'; end if;
    if outcome='PASS' then
      errors:=prepmeds_audit.evidence_deficiencies(g.group_id,e.payload,e.github_commit);
      if errors<>'[]' or verification->>'context_id' is distinct from r.context_id or verification->>'method' is distinct from 'INDEPENDENT_PRIMARY_DOCUMENT' or verification->>'mapping_adjudicated' is distinct from 'true' or verification->>'tests_passed' is distinct from 'true' or verification->>'test_commit' is distinct from e.github_commit or coalesce(verification->'discrepancies','["MISSING"]')<>'[]' then raise exception 'PASS_REQUIREMENTS_UNMET'; end if;
      if jsonb_typeof(verification->'source_checks') is distinct from 'array' then raise exception 'PRIMARY_SOURCE_CHECKS_REQUIRED'; end if;
      for s in select value from jsonb_array_elements(e.payload->'sources') loop
        select x into v from jsonb_array_elements(verification->'source_checks') x where x->>'source_id'=s->>'id';
        if not found or v->>'access' is distinct from 'VERIFIED_PRIMARY_PASSAGES' or v->>'document_sha256' is distinct from s->>'document_sha256' or v->>'primary_url' is distinct from s->>'primary_url' then raise exception 'PRIMARY_SOURCE_NOT_VERIFIED'; end if;
        for q in select value from jsonb_array_elements(s->'passages') loop
          if not coalesce((v->'passage_hashes') ? (q->>'sha256'),false) then raise exception 'SOURCE_PASSAGE_NOT_VERIFIED'; end if;
        end loop;
      end loop;
    else
      if jsonb_typeof(verification->'discrepancies') is distinct from 'array' or jsonb_array_length(verification->'discrepancies')=0 then raise exception 'FAIL_REQUIRES_DISCREPANCIES'; end if;
    end if;
    update prepmeds_audit.agent_runs set state=outcome,evidence_hash=e.content_hash,evidence_commit=e.github_commit,scenario_evidence=verification,source_citations=coalesce(verification->'source_checks','[]'),test_evidence=e.payload->'tests',discrepancies=verification->'discrepancies',result_hash=h,finished_at=clock_timestamp() where run_id=r.run_id;
    update prepmeds_audit.review_groups set state=case when outcome='PASS' then 'EVIDENCE_COMPLETE' else 'DISPUTED' end,updated_at=clock_timestamp() where group_id=g.group_id returning * into g;
    insert into prepmeds_audit.custody_events(group_id,run_id,event_type,details) values(g.group_id,r.run_id,'AGENT_B_'||outcome,jsonb_build_object('revision',e.revision,'hash',e.content_hash,'verification',verification,'a_run',e.a_run_id,'b_identity',a.identity_id));
    return jsonb_build_object('state',g.state,'revision',e.revision,'evidence_hash',e.content_hash,'clinical_reviewed',false,'patient_facing_authorized',false);
  end if;
  raise exception 'UNKNOWN_ACTION';
end $$;

-- Public invoker shim only; do not expose the private schema through PostgREST.
create or replace function public.prepmeds_agent_dispatch(p_token text,p_action text,p_payload jsonb default '{}') returns jsonb
language sql security invoker set search_path='' as $$ select prepmeds_audit.dispatch(p_token,p_action,p_payload) $$;
revoke all on all functions in schema prepmeds_audit from public,anon,authenticated,service_role;
revoke all on function public.prepmeds_agent_dispatch(text,text,jsonb) from public,anon,authenticated,service_role;
grant usage on schema prepmeds_audit to service_role;
grant execute on function prepmeds_audit.dispatch(text,text,jsonb) to service_role;
grant execute on function public.prepmeds_agent_dispatch(text,text,jsonb) to service_role;
comment on function public.prepmeds_agent_dispatch(text,text,jsonb) is 'Restricted server RPC; authenticates separately registered lane/role credentials; no clinical approval or patient activation.';
